<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{SalesOrder,SalesOrderItem,SalesReturn,SalesReturnItem}; use App\Services\{AuthorizationService,SalesNumberService,StockMovementService}; use App\Support\{Decimal,TenantContext}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class SalesReturnController { public function post(Request $r,SalesOrder $order,AuthorizationService $a,SalesNumberService $numbers,StockMovementService $movements){$t=app(TenantContext::class)->id();abort_unless($order->tenant_id===$t,404);abort_unless($a->allows($r->user(),$t,'sales.manage'),403);$d=$r->validate(['idempotency_key'=>'required|string|max:100','items'=>'required|array|min:1','items.*.sales_order_item_id'=>'required|uuid','items.*.location_id'=>'required|uuid','items.*.quantity'=>'required|numeric|min:0.000001']);if($existing=SalesReturn::where('tenant_id',$t)->where('idempotency_key',$d['idempotency_key'])->first())return response()->json(['data'=>$existing]);$ret=DB::transaction(function()use($d,$order,$r,$numbers,$movements,$t){$ret=SalesReturn::create(['tenant_id'=>$t,'sales_order_id'=>$order->id,'created_by'=>$r->user()->id,'number'=>$numbers->next($t,'return'),'state'=>'received','idempotency_key'=>$d['idempotency_key']]);foreach($d['items'] as $k=>$line){$item=SalesOrderItem::where('tenant_id',$t)->where('sales_order_id',$order->id)->whereKey($line['sales_order_item_id'])->lockForUpdate()->firstOrFail();$qty=Decimal::normalize((string)$line['quantity']);$available=Decimal::sub((string)$item->delivered_quantity,(string)$item->returned_quantity);if(Decimal::compare($qty,$available)>0)throw ValidationException::withMessages(['quantity'=>['Return exceeds delivered quantity.']]);SalesReturnItem::create(['tenant_id'=>$t,'sales_return_id'=>$ret->id,'sales_order_item_id'=>$item->id,'location_id'=>$line['location_id'],'quantity'=>$qty]);$movements->post(['tenant_id'=>$t,'variant_id'=>$item->variant_id,'location_id'=>$line['location_id'],'created_by'=>$r->user()->id,'movement_type'=>'sale_return','quantity'=>$qty,'unit_cost'=>'0','reference_type'=>'sales_return','reference_id'=>$ret->id,'idempotency_key'=>'sales-return:'.$ret->id.':'.$k]);$item->update(['returned_quantity'=>Decimal::add((string)$item->returned_quantity,$qty)]);}return $ret->load('items');});return response()->json(['data'=>$ret],201);} }
